module tb;
    reg clk;
    reg reset;
    wire [3:0] ena;
    wire [15:0] q;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .ena(ena),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    // Expected value tracking variables
    reg [3:0] exp_ones;
    reg [3:0] exp_tens;
    reg [3:0] exp_hundreds;
    reg [3:0] exp_thousands;
    reg [3:0] exp_ena;

    // Task to calculate expected values based on current state before clock edge
    // BCD counter updates synchronously on posedge clk
    task calc_expected;
        input [15:0] current_q;
        begin
            // Enables indicate when the corresponding digit is about to increment
            // Ones digit always increments every cycle (ena[0] is typically active or implied, but spec says:
            // "For digits [3:1], also output an enable signal indicating when each of the upper three digits should be incremented.")
            // Let's check standard BCD behavior:
            exp_ena[0] = (current_q[3:0] == 4'd9);
            exp_ena[1] = (current_q[3:0] == 4'd9) && (current_q[7:4] == 4'd9);
            exp_ena[2] = (current_q[3:0] == 4'd9) && (current_q[7:4] == 4'd9) && (current_q[11:8] == 4'd9);
            exp_ena[3] = 1'b0; // Top digit doesn't drive a higher enable, but ena is 4 bits wide.

            // Calculate next q values
            if (current_q[3:0] == 4'd9) begin
                exp_ones = 4'd0;
                if (current_q[7:4] == 4'd9) begin
                    exp_tens = 4'd0;
                    if (current_q[11:8] == 4'd9) begin
                        exp_hundreds = 4'd0;
                        if (current_q[15:12] == 4'd9) begin
                            exp_thousands = 4'd0;
                        end else begin
                            exp_thousands = current_q[15:12] + 1;
                        end
                    end else begin
                        exp_hundreds = current_q[11:8] + 1;
                        exp_thousands = current_q[15:12];
                    end
                end else begin
                    exp_tens = current_q[7:4] + 1;
                    exp_hundreds = current_q[11:8];
                    exp_thousands = current_q[15:12];
                end
            end else begin
                exp_ones = current_q[3:0] + 1;
                exp_tens = current_q[7:4];
                exp_hundreds = current_q[11:8];
                exp_thousands = current_q[15:12];
            end
        end
    endtask

    initial begin
        clk = 0;
        reset = 1;

        // Test 1: Reset behavior
        #12;
        if (q !== 16'h0000) begin
            $display("ERROR: Reset failed. q = %h (expected 0000)", q);
            errors = errors + 1;
        end
        if (ena !== 4'b0000) begin
            // Depending on design, ena might be 0 or combinatorial check. Let's check case inequality.
            // We will evaluate standard checks rigorously.
        end

        // Release reset
        @(negedge clk);
        reset = 0;

        // Test 2: Run through initial count and verify sequence up to rollover points
        // We will check 150 cycles to thoroughly test multiple rollovers (9 -> 10, 99 -> 100, 999 -> 1000)
        for (i = 0; i < 1200; i = i + 1) begin
            // Compute what next state should be based on current q before clock edge
            calc_expected(q);

            @(posedge clk);
            #2; // Small delay to let outputs settle

            // Verify outputs using case inequality (`!==`)
            if (q[3:0] !== exp_ones) begin
                get_error();
                $display("Time %0t: Mismatch in ones digit! Got %h, Expected %h", $time, q[3:0], exp_ones);
            end
            if (q[7:4] !== exp_tens) begin
                get_error();
                $display("Time %0t: Mismatch in tens digit! Got %h, Expected %h", $time, q[7:4], exp_tens);
            end
            if (q[11:8] !== exp_hundreds) begin
                get_error();
                $display("Time %0t: Mismatch in hundreds digit! Got %h, Expected %h", $time, q[11:8], exp_hundreds);
            end
            if (q[15:12] !== exp_thousands) begin
                get_error();
                $display("Time %0t: Mismatch in thousands digit! Got %h, Expected %h", $time, q[15:12], exp_thousands);
            end

            // Check enables for digits [3:1] (which correspond to ena[0], ena[1], ena[2] or similar mapping, 
            // spec says "For digits [3:1], also output an enable signal indicating when each of the upper three digits should be incremented.")
            // Usually ena[0] is tens enable, ena[1] is hundreds enable, ena[2] is thousands enable. 
            // Let's verify against expected enables.
            if (ena[0] !== exp_ena[0]) begin
                get_error();
                $display("Time %0t: Mismatch in ena[0]! Got %b, Expected %b", $time, ena[0], exp_ena[0]);
            end
            if (ena[1] !== exp_ena[1]) begin
                get_error();
                $display("Time %0t: Mismatch in ena[1]! Got %b, Expected %b", $time, ena[1], exp_ena[1]);
            end
            if (ena[2] !== exp_ena[2]) begin
                get_error();
                $display("Time %0t: Mismatch in ena[2]! Got %b, Expected %b", $time, ena[2], exp_ena[2]);
            end
        end

        // Test 3: Synchronous Reset mid-operation
        @(negedge clk);
        reset = 1;
        @(posedge clk);
        #2;
        if (q !== 16'h0000) begin
            $display("ERROR: Synchronous reset failed mid-operation. q = %h", q);
            errors = errors + 1;
        end

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

    task get_error;
        begin
            errors = errors + 1;
        end
    endtask

endmodule
